package com.zdm.platform.account;

import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.simple.SimpleJdbcInsert;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Account IDs identify people; released phone credentials must never reconnect their history. */
@Service
public class AccountLifecycleService {
  public enum Disposition { KEEP, RELEASE_PHONE, DELETE }
  public record Account(Long id, String name, String gender, String status, boolean created) {}
  private record Reference(String table, String column) {}
  private static final Set<String> TENANT_PURGED_TABLES = Set.of(
      "employees", "roles", "employee_invites", "product_categories", "stores");
  private final com.zdm.platform.storeexit.StoreExitAccountReferences exitAccountReferences;
  private final JdbcTemplate jdbc;
  private final SimpleJdbcInsert insert;
  private final com.zdm.platform.storeexit.HistoricIdentifierGuard historicIds;
  private final com.zdm.platform.storeexit.StoreExitRegistry exitRegistry;

  public AccountLifecycleService(JdbcTemplate jdbc, com.zdm.platform.storeexit.HistoricIdentifierGuard historicIds,
      com.zdm.platform.storeexit.StoreExitRegistry exitRegistry,
      com.zdm.platform.storeexit.StoreExitAccountReferences exitAccountReferences) {
    this.exitAccountReferences = exitAccountReferences;
    this.historicIds = historicIds;
    this.exitRegistry = exitRegistry;
    this.jdbc = jdbc;
    this.insert = new SimpleJdbcInsert(jdbc).withTableName("accounts")
        .usingColumns("phone", "display_name", "account_type", "status").usingGeneratedKeyColumns("id");
  }

  public Optional<Account> findByPhoneForUpdate(String phone) {
    // Match deletion's primary-key lock order; locking the phone index first can deadlock.
    List<Long> candidates = jdbc.queryForList("SELECT id FROM accounts WHERE phone = ?", Long.class, phone);
    if (candidates.isEmpty()) {
      return Optional.empty();
    }
    Optional<Account> existing = jdbc.query("SELECT id, display_name, gender, status FROM accounts FORCE INDEX (PRIMARY) WHERE id = ? AND phone = ? FOR UPDATE",
        (rs, row) -> new Account(rs.getLong("id"), rs.getString("display_name"), rs.getString("gender"), rs.getString("status"), false),
        candidates.getFirst(), phone).stream().findFirst();
    return existing.map(this::requireReusableAccount);
  }

  private Account requireReusableAccount(Account account) {
    var history = historicIds.accountExitState(account.id());
    if (history.retired() || (!history.uncertainStores().isEmpty()
        && assessForExit(account.id(), history.uncertainStores(), null) == Disposition.DELETE)) {
      throw new IllegalStateException("该账号的退出结果尚待恢复核验，不能复用历史账号");
    }
    return account;
  }

  @Transactional
  public Account findOrCreate(String phone, String name) {
    Optional<Account> existing = findByPhoneForUpdate(phone);
    if (existing.isPresent()) {
      return existing.get();
    }
    try {
      long watermark = historicIds.reserve("accounts");
      Long id = insert.executeAndReturnKey(Map.of(
          "phone", phone, "display_name", name, "account_type", "person", "status", "enabled")).longValue();
      id = historicIds.skipReserved("accounts", id, watermark);
      return new Account(id, name, null, "enabled", true);
    } catch (DuplicateKeyException exception) {
      // Duplicate insert establishes a current unique-key conflict. Do not reread an older snapshot.
      return jdbc.query("SELECT id, display_name, gender, status FROM accounts WHERE phone=? FOR UPDATE",
          (rs, row) -> new Account(rs.getLong("id"), rs.getString("display_name"), rs.getString("gender"), rs.getString("status"), false),
          phone).stream().findFirst().map(this::requireReusableAccount).orElseThrow(() -> exception);
    }
  }

  @Transactional
  public Account findOrCreate(String phone, String name, String gender) {
    Account account = findOrCreate(phone, name);
    if (account.created()) {
      updatePersonalProfile(account.id(), name, gender);
      return new Account(account.id(), name, gender, account.status(), true);
    }
    return account;
  }

  public void updatePersonalProfile(Long accountId, String name, String gender) {
    if (!org.springframework.util.StringUtils.hasText(name)
        || (gender != null && !List.of("male", "female").contains(gender))) {
      throw new IllegalArgumentException("请填写姓名并选择有效性别");
    }
    jdbc.update("UPDATE accounts SET display_name=?,gender=? WHERE id=?", name.trim(), gender, accountId);
  }

  public void lockAccount(Long accountId) {
    if (accountId != null) {
      List<Long> ids = jdbc.queryForList("SELECT id FROM accounts WHERE id = ? FOR UPDATE", Long.class, accountId);
      if (ids.isEmpty()) {
        throw new IllegalArgumentException("账号已变更，请刷新后重试");
      }
    }
  }

  public boolean isProtected(Long accountId) {
    return accountId != null && (accountId == 1L
        || exists("SELECT 1 FROM accounts WHERE id=? AND account_type <> 'person'", accountId)
        || exists("SELECT 1 FROM account_identities WHERE account_id=? AND identity_type='platform_admin'", accountId)
        || exists("SELECT 1 FROM account_roles ar JOIN roles r ON r.id=ar.role_id WHERE ar.account_id=? AND r.code='SUPER_ADMIN'", accountId));
  }

  /** Preview the result after deleting the specified tenant, or classify current references when null. */
  public Disposition assess(Long accountId, Long removedTenantId) {
    if (accountId == null || isProtected(accountId) || hasMembership(accountId, removedTenantId)) {
      return Disposition.KEEP;
    }
    return hasHistory(accountId, removedTenantId) ? Disposition.RELEASE_PHONE : Disposition.DELETE;
  }

  private boolean hasMembership(Long accountId, Long removedTenantId) {
    String scope = removedTenantId == null ? "" : " AND (tenant_id IS NULL OR tenant_id <> " + removedTenantId + ")";
    if (exists("SELECT 1 FROM employees WHERE account_id=?" + scope, accountId)
        || exists("SELECT 1 FROM account_roles WHERE account_id=?" + scope, accountId)) {
      return true;
    }
    String identityScope = removedTenantId == null ? ""
        : " AND (i.tenant_id IS NULL OR i.tenant_id <> " + removedTenantId + ")";
    // A disabled employee still counts. A legacy identity whose employee was deleted does not.
    return exists("""
        SELECT 1 FROM account_identities i WHERE i.account_id=?
          AND (i.identity_type <> 'employee' OR EXISTS (
            SELECT 1 FROM employees e WHERE e.id=i.subject_id AND e.account_id=i.account_id
              AND e.client_code=i.client_code AND e.tenant_id <=> i.tenant_id AND e.store_id <=> i.store_id))
        """ + identityScope, accountId);
  }

  private boolean hasHistory(Long accountId, Long removedTenantId) {
    return hasHistory(accountId, removedTenantId, Set.of());
  }

  private boolean hasHistory(Long accountId, Long removedTenantId, Set<Long> removedStores) {
    // Include conventional account columns AND foreign keys, including references without FK constraints.
    List<Reference> references = jdbc.query("""
        SELECT TABLE_NAME, COLUMN_NAME FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA=DATABASE() AND (COLUMN_NAME='account_id' OR RIGHT(COLUMN_NAME,11)='_account_id')
        UNION
        SELECT TABLE_NAME, COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE
        WHERE TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_SCHEMA=DATABASE()
          AND REFERENCED_TABLE_NAME='accounts' AND REFERENCED_COLUMN_NAME='id'
        """, (rs, row) -> new Reference(rs.getString("TABLE_NAME"), rs.getString("COLUMN_NAME")));
    for (Reference ref : references) {
      if (Set.of("accounts", "auth_sessions", "account_identities", "account_roles").contains(ref.table())
          || ("employees".equals(ref.table()) && "account_id".equals(ref.column()))) {
        continue;
      }
      String scope = storeRemovalClause(ref, removedStores);
      if (removedTenantId != null) {
        if (TENANT_PURGED_TABLES.contains(ref.table())) {
          scope += " AND (tenant_id IS NULL OR tenant_id <> " + removedTenantId + ")";
        } else if ("store_categories".equals(ref.table())) {
          scope += " AND store_id NOT IN (SELECT id FROM stores WHERE tenant_id=" + removedTenantId + ")";
        } else if ("tenants".equals(ref.table())) {
          scope += " AND id <> " + removedTenantId;
        } else if ("category_template_versions".equals(ref.table())) {
          scope += " AND category_id NOT IN (SELECT id FROM product_categories WHERE tenant_id=" + removedTenantId + ")";
        }
      }
      if (exists("SELECT 1 FROM " + identifier(ref.table()) + " WHERE " + identifier(ref.column()) + "=?" + scope, accountId)) {
        return true;
      }
    }
    return false;
  }

  private String identifier(String name) {
    if (!name.matches("[a-zA-Z0-9_]+")) {
      throw new IllegalStateException("无法确认账号引用字段");
    }
    return "`" + name + "`";
  }

  @Transactional
  public Disposition releaseIfUnbound(Long accountId) {
    if (accountId == null) {
      return Disposition.KEEP;
    }
    lockAccount(accountId);
    Disposition result = assess(accountId, null);
    if (result == Disposition.KEEP) {
      return result;
    }
    jdbc.update("DELETE FROM auth_sessions WHERE account_id=?", accountId);
    // Only dangling identities remain here; live disabled relationships were checked above.
    jdbc.update("DELETE FROM account_identities WHERE account_id=?", accountId);
    if (result == Disposition.RELEASE_PHONE) {
      jdbc.update("UPDATE accounts SET phone=NULL,status='disabled' WHERE id=?", accountId);
    } else {
      jdbc.update("DELETE FROM accounts WHERE id=?", accountId);
    }
    return result;
  }

  public boolean hasPhoneCredential(Long accountId) {
    return !jdbc.queryForList("SELECT id FROM accounts WHERE id=? AND phone IS NOT NULL AND TRIM(phone)<>'' LIMIT 1 FOR UPDATE", Long.class, accountId).isEmpty();
  }

  /** Only references in rows this exit will remove; never a global orphan-account sweep. */
  public List<Long> storeExitCandidates(com.zdm.platform.storeexit.StoreExitScope scope) {
    java.util.Set<Long> result = new java.util.TreeSet<>(storeExitRelationshipCandidates(scope.storeId()));
    for (var module : exitRegistry.modules()) {
      result.addAll(module.referencedAccounts(jdbc, scope, exitAccountReferences));
    }
    for (String field : exitAccountReferences.liveFields("stores")) {
      if (!field.matches("[a-z_]+")) { throw new IllegalStateException("账号引用字段不合法"); }
      result.addAll(jdbc.queryForList("SELECT " + field + " FROM stores WHERE id=? AND tenant_id=? AND "
          + field + " IS NOT NULL AND EXISTS(SELECT 1 FROM accounts a WHERE a.id=stores." + field + ")",
          Long.class, scope.storeId(), scope.tenantId()));
    }
    return List.copyOf(result);
  }

  public List<Long> storeExitRelationshipCandidates(long storeId) {
    return jdbc.queryForList("""
        SELECT account_id FROM account_identities WHERE store_id=?
        UNION SELECT account_id FROM employees WHERE store_id=? AND account_id IS NOT NULL
        UNION SELECT account_id FROM account_roles WHERE store_id=? ORDER BY account_id
        """, Long.class, storeId, storeId, storeId);
  }

  /** Store exit is deliberately separate from normal employee/identity retirement. */
  @Transactional
  public Disposition releaseForStoreExit(Long accountId) {
    if (accountId == null) { return Disposition.KEEP; }
    lockAccount(accountId);
    if (assessForExit(accountId, Set.of(), null) == Disposition.KEEP) { return Disposition.KEEP; }
    if (requiresHistoricalName(accountId)) {
    jdbc.update("""
        INSERT INTO store_exit_actor_snapshots(account_id,display_name_at_exit)
        SELECT id,display_name FROM accounts WHERE id=?
        ON DUPLICATE KEY UPDATE account_id=store_exit_actor_snapshots.account_id
        """, accountId);
    }
    jdbc.update("DELETE FROM auth_sessions WHERE account_id=?", accountId);
    jdbc.update("DELETE FROM accounts WHERE id=?", accountId);
    return Disposition.DELETE;
  }

  public boolean requiresHistoricalName(Long accountId) {
    for (String field : exitAccountReferences.historicalFields()) {
      String[] parts = field.split("\\.", 2);
      if ("store_exit_actor_snapshots".equals(parts[0])) { continue; }
      if (exists("SELECT 1 FROM " + identifier(parts[0]) + " WHERE " + identifier(parts[1]) + "=?", accountId)) { return true; }
    }
    return false;
  }

  /** Capture before tenant cleanup: tenant-owned identities keep their original retirement policy. */
  public boolean isStoreOnlyExitAccount(Long accountId, long tenantId) {
    String tenantScope = " AND tenant_id=" + tenantId;
    if (exists("SELECT 1 FROM tenants WHERE account_id=? AND id=" + tenantId, accountId)) { return false; }
    boolean storeRelation = false;
    for (String table : List.of("account_identities", "employees", "account_roles")) {
      if (exists("SELECT 1 FROM " + table + " WHERE account_id=?" + tenantScope + " AND store_id IS NULL", accountId)) { return false; }
      storeRelation |= exists("SELECT 1 FROM " + table + " WHERE account_id=?" + tenantScope + " AND store_id IS NOT NULL", accountId);
    }
    if (storeRelation) { return true; }
    // A prior store exit may have removed every identity while another store's live reference retained this account.
    for (Long store : jdbc.queryForList("SELECT id FROM stores WHERE tenant_id=? ORDER BY id", Long.class, tenantId)) {
      if (storeExitCandidates(com.zdm.platform.storeexit.StoreExitScope.capture(jdbc, store, tenantId)).contains(accountId)) {
        return true;
      }
    }
    return false;
  }

  public Disposition assessForTenantExit(Long accountId, Set<Long> removedStores, long tenantId) {
    if (isStoreOnlyExitAccount(accountId, tenantId)) { return assessForExit(accountId, removedStores, tenantId); }
    if (accountId == null || isProtected(accountId) || hasMembership(accountId, tenantId)) { return Disposition.KEEP; }
    return hasHistory(accountId, tenantId, removedStores) ? Disposition.RELEASE_PHONE : Disposition.DELETE;
  }

  /** Read-only projection of the same live-reference policy used after actual cleanup. */
  public Disposition assessForExit(Long accountId, Set<Long> removedStores, Long removedTenant) {
    if (accountId == null || isProtected(accountId)) { return Disposition.KEEP; }
    List<Reference> references = jdbc.query("""
        SELECT TABLE_NAME,COLUMN_NAME FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA=DATABASE() AND (COLUMN_NAME='account_id' OR RIGHT(COLUMN_NAME,11)='_account_id')
        UNION SELECT TABLE_NAME,COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE
        WHERE TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_SCHEMA=DATABASE()
          AND REFERENCED_TABLE_NAME='accounts' AND REFERENCED_COLUMN_NAME='id'
        """, (rs, row) -> new Reference(rs.getString(1), rs.getString(2)));
    for (Reference reference : references) {
      if (java.util.Set.of("accounts", "auth_sessions").contains(reference.table())
          || exitAccountReferences.historical(reference.table() + "." + reference.column())) { continue; }
      String remaining = storeRemovalClause(reference, removedStores);
      if (removedTenant != null) {
        if (TENANT_PURGED_TABLES.contains(reference.table()) || java.util.Set.of("account_identities", "account_roles").contains(reference.table())) {
          if ("stores".equals(reference.table()) || !"store_categories".equals(reference.table())) {
            remaining += " AND (tenant_id IS NULL OR tenant_id<>" + removedTenant + ")";
          }
        } else if ("tenants".equals(reference.table())) { remaining += " AND id<>" + removedTenant; }
        else if ("category_template_versions".equals(reference.table())) {
          remaining += " AND category_id NOT IN (SELECT id FROM product_categories WHERE tenant_id=" + removedTenant + ")";
        }
      }
      // Remaining operational references still use the live account (including current creator names).
      if (exists("SELECT 1 FROM " + identifier(reference.table()) + " WHERE " + identifier(reference.column()) + "=?" + remaining, accountId)) {
        return Disposition.KEEP;
      }
    }
    return Disposition.DELETE;
  }

  private String storeRemovalClause(Reference reference, Set<Long> removedStores) {
    String remaining = "";
      if (!removedStores.isEmpty() && (exitRegistry.tables().contains(reference.table()) || "stores".equals(reference.table()))) {
        String ids = removedStores.stream().sorted().map(String::valueOf).collect(java.util.stream.Collectors.joining(","));
        if ("stores".equals(reference.table())) { remaining += " AND id NOT IN (" + ids + ")"; }
        else if (java.util.Objects.requireNonNull(jdbc.queryForObject("""
            SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE()
            AND TABLE_NAME=? AND COLUMN_NAME='store_id'
            """, Integer.class, reference.table()), "数量查询缺少结果") > 0) {
          remaining += " AND (store_id IS NULL OR store_id NOT IN (" + ids + "))";
        } else if ("store_customer_followups".equals(reference.table())) {
          remaining += " AND customer_id NOT IN (SELECT id FROM store_customers WHERE store_id IN (" + ids + "))";
        } else if ("store_finished_sale_prices".equals(reference.table())) {
          remaining += " AND listing_id NOT IN (SELECT id FROM store_finished_products WHERE store_id IN (" + ids + "))";
        } else if ("store_accessory_sale_prices".equals(reference.table())) {
          remaining += " AND listing_id NOT IN (SELECT id FROM store_accessory_products WHERE store_id IN (" + ids + "))";
        } else if ("employee_invite_acceptances".equals(reference.table())) {
          remaining += " AND invite_id NOT IN (SELECT id FROM employee_invites WHERE store_id IN (" + ids + "))";
        } else if ("product_state_activity".equals(reference.table())) {
          remaining += " AND NOT(business_client_code='store' AND ((kind='store-finished' AND record_id IN "
              + "(SELECT id FROM store_finished_products WHERE store_id IN (" + ids + "))) OR (kind='store-accessory' AND record_id IN "
              + "(SELECT id FROM store_accessory_products WHERE store_id IN (" + ids + ")))))";
        }
      }
    return remaining;
  }

  private boolean exists(String sql, Long accountId) {
    // A locking read sees memberships committed before our account lock, even under REPEATABLE READ.
    return !jdbc.queryForList(sql + " LIMIT 1 FOR UPDATE", accountId).isEmpty();
  }
}

package com.zdm.platform.storeexit;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Component;

/** Explicitly reviewed purpose per field; an unknown account reference cannot silently keep or remove an account. */
@Component
public final class StoreExitAccountReferences {
  private final JsonNode references;
  public StoreExitAccountReferences(ObjectMapper json) {
    try (var input = new ClassPathResource("store-exit-coverage.json").getInputStream()) {
      references = json.readTree(input).path("accountReferences");
    } catch (java.io.IOException exception) { throw new IllegalStateException("账号退出引用登记不可读", exception); }
  }
  public java.util.Set<String> historicalFields() {
    java.util.Set<String> fields = new java.util.HashSet<>();
    references.fields().forEachRemaining(entry -> {
      if ("history".equals(entry.getValue().path("kind").asText())) { fields.add(entry.getKey()); }
    });
    return java.util.Set.copyOf(fields);
  }

  public java.util.Set<String> liveFields(String table) {
    java.util.Set<String> fields = new java.util.TreeSet<>();
    references.fields().forEachRemaining(entry -> {
      if (entry.getKey().startsWith(table + ".") && "live".equals(entry.getValue().path("kind").asText())) {
        fields.add(entry.getKey().substring(table.length() + 1));
      }
    });
    return java.util.Set.copyOf(fields);
  }

  public boolean historical(String field) {
    String kind = references.path(field).path("kind").asText();
    if (!java.util.Set.of("history", "live").contains(kind)) { throw new IllegalStateException("账号引用用途尚未登记：" + field); }
    return "history".equals(kind);
  }
}

package com.zdm.platform.storeexit;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.zdm.platform.account.AccountLifecycleService;
import com.zdm.platform.security.CurrentIdentity;
import com.zdm.platform.security.CurrentIdentityProvider;
import com.zdm.platform.security.DataScope;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class StoreExitCoordinator {
  public static final String RULE_VERSION = "V1.3";
  private static final Logger LOG = LoggerFactory.getLogger(StoreExitCoordinator.class);
  private final JdbcTemplate jdbc;
  private final StoreExitRegistry registry;
  private final StoreExitCoverage coverage;
  private final StoreExitJournal journal;
  private final StoreExitMedia media;
  private final AccountLifecycleService accounts;
  private final CurrentIdentityProvider identities;
  private final ObjectMapper json;
  private final TransactionTemplate auditTransaction;
  private final StoreExitRecoveryState recovery;
  private final StoreExitMediaFollowup mediaFollowup;
  private final com.zdm.platform.security.SecurityAuditService securityAudit;

  public StoreExitCoordinator(JdbcTemplate jdbc, StoreExitRegistry registry, StoreExitCoverage coverage,
      StoreExitJournal journal, StoreExitMedia media, AccountLifecycleService accounts,
      CurrentIdentityProvider identities, ObjectMapper json, PlatformTransactionManager transactions,
      StoreExitRecoveryState recovery, StoreExitMediaFollowup mediaFollowup,
      com.zdm.platform.security.SecurityAuditService securityAudit) {
    this.jdbc = jdbc; this.registry = registry; this.coverage = coverage; this.journal = journal;
    this.media = media; this.accounts = accounts; this.identities = identities; this.json = json;
    this.recovery = recovery;
    this.mediaFollowup = mediaFollowup; this.securityAudit = securityAudit;
    auditTransaction = new TransactionTemplate(transactions);
    auditTransaction.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);
  }

  public StoreExitPreview preview(long storeId) { return preview(storeId, false); }

  public StoreExitPreview previewForTenant(long storeId) { return preview(storeId, true); }

  private StoreExitPreview preview(long storeId, boolean tenantExit) {
    Map<String, Object> store = target(storeId, false);
    authorize(store, tenantExit);
    recovery.refresh();
    recovery.requireAvailable(storeId);
    long tenantId = number(store.get("tenant_id"));
    StoreExitScope scope = StoreExitScope.capture(jdbc, storeId, tenantId);
    List<String> blockers = new ArrayList<>();
    if (!"disabled".equals(store.get("status"))) { blockers.add("请先归档门店"); }
    String schema = "";
    try { schema = coverage.verify(); } catch (IllegalStateException e) { blockers.add(e.getMessage()); }
    try { journal.requireReady(); } catch (IllegalStateException e) { blockers.add(e.getMessage()); }
    if (foreignReferences(scope)) { blockers.add("该门店仍有跨组织引用，不能彻底删除"); }
    if (!securityAudit.storeHistoryVerifiable(scope.ids("account_identities"))) {
      blockers.add("门店历史安全审计的身份归属无法核实");
    }
    Map<String, Long> counts = new LinkedHashMap<>();
    registry.modules().forEach(module -> counts.putAll(inspectModule(module, scope)));
    counts.put("media_lifecycle_candidates", (long) media.mediaIds(scope).size());
    java.util.Set<Long> removedStores = tenantExit ? new java.util.HashSet<>(jdbc.queryForList(
        "SELECT id FROM stores WHERE tenant_id=?", Long.class, tenantId)) : java.util.Set.of(storeId);
    var relationshipAccounts = accounts.storeExitRelationshipCandidates(storeId);
    var candidateAccounts = accounts.storeExitCandidates(scope);
    Map<Long, String> accountDecisions = new java.util.TreeMap<>();
    long deletedAccounts = 0; long releasedPhones = 0; long retainedAccounts = 0;
    for (Long account : candidateAccounts) {
      var disposition = tenantExit ? accounts.assessForTenantExit(account, removedStores, tenantId)
          : accounts.assessForExit(account, removedStores, null);
      boolean releasePhone = disposition == AccountLifecycleService.Disposition.DELETE && accounts.hasPhoneCredential(account);
      accountDecisions.put(account, disposition.name() + ":" + releasePhone);
      if (disposition == AccountLifecycleService.Disposition.DELETE) { deletedAccounts++; }
      if (releasePhone) { releasedPhones++; }
      if (disposition != AccountLifecycleService.Disposition.DELETE && relationshipAccounts.contains(account)) { retainedAccounts++; }
    }
    counts.put("accounts_delete", deletedAccounts);
    counts.put("accounts_retained", retainedAccounts);
    counts.put("phones_released", releasedPhones);
    List<String> retained = List.of("共享商品、SKU、库存及其他组织数据保留",
        "平台安全审计、最小退出凭证及必要任务按规则保留", "媒体按有效引用和既有生命周期处理；不清理备份或承诺擦除离线副本");
    String hash = StoreExitCoverage.hash(RULE_VERSION + schema + encode(new java.util.TreeMap<>(counts))
        + scope.storeId() + "/" + scope.tenantId() + encode(new java.util.TreeMap<>(scope.parentIds()))
        + encode(media.mediaIds(scope)) + encode(accountDecisions) + String.valueOf(store.get("name")));
    return new StoreExitPreview(storeId, tenantId, String.valueOf(store.get("name")), RULE_VERSION, hash, counts, retained, blockers);
  }

  /** Called only from a transaction holding the tenant lock before all store locks. */
  public void lockTenantStores(long tenantId) {
    jdbc.queryForList("SELECT id FROM stores WHERE tenant_id=? ORDER BY id FOR UPDATE", Long.class, tenantId);
  }

  @Transactional(propagation = Propagation.MANDATORY)
  public List<Long> execute(long storeId, String confirmedHash, boolean tenantExit) {
    Map<String, Object> store = target(storeId, true);
    authorize(store, tenantExit);
    StoreExitPreview preview = preview(storeId, tenantExit);
    if (!preview.eligible()) { throw new IllegalArgumentException(preview.blockers().getFirst()); }
    if (confirmedHash == null || !confirmedHash.equals(preview.planHash())) {
      throw new IllegalArgumentException("删除范围或规则已变化，请重新预检并确认");
    }
    StoreExitScope scope = StoreExitScope.capture(jdbc, storeId, preview.tenantId());
    List<Long> accountIds = accounts.storeExitCandidates(scope);
    if (tenantExit) {
      java.util.Set<Long> all = new java.util.TreeSet<>(accountIds);
      all.addAll(jdbc.queryForList("""
          SELECT account_id FROM account_identities WHERE tenant_id=?
          UNION SELECT account_id FROM employees WHERE tenant_id=? AND account_id IS NOT NULL
          UNION SELECT account_id FROM account_roles WHERE tenant_id=?
          UNION SELECT account_id FROM tenants WHERE id=? ORDER BY account_id
          """, Long.class, scope.tenantId(), scope.tenantId(), scope.tenantId(), scope.tenantId()));
      for (Long id : jdbc.queryForList("SELECT id FROM stores WHERE tenant_id=? ORDER BY id", Long.class, scope.tenantId())) {
        all.addAll(accounts.storeExitCandidates(StoreExitScope.capture(jdbc, id, scope.tenantId())));
      }
      accountIds = List.copyOf(all);
    }
    accountIds.forEach(accounts::lockAccount);
    String operation = UUID.randomUUID().toString();
    CurrentIdentity actor = identities.require();
    try { journal.intent(operation, storeId, scope.tenantId(), accountIds, actor); }
    catch (RuntimeException exception) {
      recovery.fence(storeId);
      try { journal.append(operation, storeId, scope.tenantId(), "ROLLED_BACK"); }
      catch (RuntimeException pending) { LOG.error("Store exit acceptance outcome unresolved: {}", operation, pending); }
      recovery.refresh(); throw exception;
    }
    recovery.begin(operation, storeId);
    TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
      @Override public void afterCompletion(int status) {
        recovery.finish(operation, storeId, status == STATUS_COMMITTED);
        String outcome = status == STATUS_COMMITTED ? "COMMITTED" : status == STATUS_ROLLED_BACK ? "ROLLED_BACK" : "UNKNOWN";
        if (!"UNKNOWN".equals(outcome)) {
          try {
            if ("COMMITTED".equals(outcome)) {
              journal.committed(jdbc.queryForMap("SELECT * FROM store_exit_operations WHERE operation_id=?", operation));
            } else { journal.append(operation, storeId, scope.tenantId(), outcome); }
          }
          catch (RuntimeException exception) { LOG.error("Store exit journal outcome pending: {}", operation, exception); }
        }
        if (status != STATUS_COMMITTED) {
          auditFailure(operation, storeId, scope.tenantId(), actor.accountId(), outcome);
        }
        recovery.refresh();
      }
    });
    List<Long> mediaIds = media.mediaIds(scope);
    jdbc.update("INSERT INTO store_exit_tasks(operation_id,media_id) VALUES (?,0)", operation);
    String tenantName = jdbc.queryForObject("SELECT a.display_name FROM tenants t JOIN accounts a ON a.id=t.account_id WHERE t.id=?", String.class, scope.tenantId());
    media.release(scope, operation, mediaIds);
    securityAudit.preserveStoreHistory(scope.storeId(), scope.tenantId(), scope.ids("account_identities"), preview.storeName(), tenantName, null);
    for (StoreExitModule module : registry.modules()) { module.execute(jdbc, scope); }
    jdbc.update("DELETE FROM stores WHERE id=? AND tenant_id=? AND status='disabled'", storeId, scope.tenantId());
    for (StoreExitModule module : registry.modules()) {
      module.verify(jdbc, scope);
      if (inspectModule(module, scope).values().stream().anyMatch(count -> count > 0)) {
        throw new IllegalStateException("门店退出模块仍有应删数据：" + module.id());
      }
    }
    media.verify(scope);
    if (java.util.Objects.requireNonNull(jdbc.queryForObject("SELECT COUNT(*) FROM stores WHERE id=?", Long.class, storeId), "数量查询缺少结果") != 0) {
      throw new IllegalStateException("门店主档残留校验失败");
    }
    jdbc.update("""
        INSERT INTO store_exit_operations
          (operation_id,store_id,tenant_id,store_name,tenant_name,store_created_by_account_id,operator_account_id,operator_name,
           operator_identity,rule_version,plan_hash,status,result_json)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,CAST(? AS JSON))
        """, operation, storeId, scope.tenantId(), preview.storeName(), tenantName, store.get("created_by_account_id"), actor.accountId(), actor.displayName(),
        actor.clientCode() + ":" + actor.identityId(), RULE_VERSION, confirmedHash, "DB_COMMITTED",
        encode(Map.of("counts", preview.counts(), "retained", preview.retained(), "verified", true,
            "mediaRelease", media.releaseCheckpoints(mediaIds), "accountIds", accountIds.stream().map(String::valueOf).toList())));
    return accountIds;
  }

  @Transactional(propagation = Propagation.MANDATORY)
  public void recordAccountOutcome(long storeId, List<Long> candidates) {
    List<String> deleted = candidates.stream().filter(account -> java.util.Objects.requireNonNull(jdbc.queryForObject(
        "SELECT COUNT(*) FROM accounts WHERE id=?", Long.class, account), "数量查询缺少结果") == 0).map(String::valueOf).toList();
    Map<String, String> snapshots = new java.util.TreeMap<>();
    for (String account : deleted) {
      jdbc.query("SELECT display_name_at_exit FROM store_exit_actor_snapshots WHERE account_id=?",
          (org.springframework.jdbc.core.RowCallbackHandler) row -> snapshots.put(account, row.getString(1)), Long.parseLong(account));
    }
    jdbc.update("UPDATE store_exit_operations SET result_json=JSON_SET(result_json,'$.accountIds',CAST(? AS JSON),'$.actorSnapshots',CAST(? AS JSON)) WHERE store_id=?",
        encode(deleted), encode(snapshots), storeId);
  }

  public void requireTenantLock(long tenantId) {
    if (jdbc.queryForList("SELECT id FROM tenants WHERE id=? FOR UPDATE", Long.class, tenantId).isEmpty()) {
      throw new IllegalArgumentException("租户不存在");
    }
  }

  /** Only a durable, independently stored COMMITTED receipt may authorize restoration cleanup. */
  @Transactional(isolation = org.springframework.transaction.annotation.Isolation.READ_COMMITTED)
  public void reapplyAfterRestore(StoreExitJournal.Entry entry) {
    if (!"COMMITTED".equals(entry.stage()) || !journal.entries().contains(entry)) {
      throw new IllegalArgumentException("恢复清理缺少可信成功凭证");
    }
    coverage.verify();
    jdbc.queryForList("SELECT id FROM tenants WHERE id=? FOR UPDATE", Long.class, entry.tenantId());
    var restored = jdbc.queryForList("SELECT tenant_id FROM stores WHERE id=? FOR UPDATE", entry.storeId());
    if (!restored.isEmpty() && number(restored.getFirst().get("tenant_id")) != entry.tenantId()) {
      throw new IllegalStateException("恢复对象归属与独立凭证不一致");
    }
    StoreExitScope scope = StoreExitScope.capture(jdbc, entry.storeId(), entry.tenantId());
    if (foreignReferences(scope)) { throw new IllegalStateException("恢复清理存在未解决外部引用"); }
    java.util.Set<Long> recoveryAccounts = new java.util.TreeSet<>(accounts.storeExitCandidates(scope));
    try {
      var receipt = json.readTree(String.valueOf(entry.receipt().get("result_json")));
      for (var id : receipt.path("accountIds")) {
        long account = Long.parseLong(id.asText());
        if (!jdbc.queryForList("SELECT id FROM accounts WHERE id=?", Long.class, account).isEmpty()) { recoveryAccounts.add(account); }
      }
    } catch (JsonProcessingException | NumberFormatException exception) {
      throw new IllegalStateException("退出账号恢复凭证不可核实", exception);
    }
    List<Long> accountIds = List.copyOf(recoveryAccounts);
    accountIds.forEach(accounts::lockAccount);
    List<Long> mediaIds = media.mediaIds(scope);
    media.release(scope, entry.operationId(), mediaIds);
    securityAudit.preserveStoreHistory(scope.storeId(), scope.tenantId(), scope.ids("account_identities"),
        String.valueOf(entry.receipt().get("store_name")), String.valueOf(entry.receipt().get("tenant_name")), String.valueOf(entry.receipt().get("created_at")));
    try {
      media.restoreCheckpoints(entry.operationId(), mediaIds,
          json.readTree(String.valueOf(entry.receipt().get("result_json"))).path("mediaRelease"));
    } catch (JsonProcessingException exception) { throw new IllegalStateException("独立凭证媒体起算记录损坏", exception); }
    for (StoreExitModule module : registry.modules()) { module.execute(jdbc, scope); }
    jdbc.update("DELETE FROM stores WHERE id=? AND tenant_id=?", entry.storeId(), entry.tenantId());
    for (StoreExitModule module : registry.modules()) {
      module.verify(jdbc, scope);
      if (inspectModule(module, scope).values().stream().anyMatch(count -> count > 0)) {
        throw new IllegalStateException("门店退出模块仍有应删数据：" + module.id());
      }
    }
    media.verify(scope);
    var receipt = entry.receipt();
    jdbc.update("""
        INSERT INTO store_exit_operations
          (operation_id,store_id,tenant_id,store_name,tenant_name,store_created_by_account_id,operator_account_id,operator_name,
           operator_identity,rule_version,plan_hash,status,result_json,created_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,'DB_COMMITTED',CAST(? AS JSON),?)
        ON DUPLICATE KEY UPDATE status='DB_COMMITTED'
        """, entry.operationId(), entry.storeId(), entry.tenantId(), receipt.get("store_name"), receipt.get("tenant_name"),
        receipt.get("store_created_by_account_id"), receipt.get("operator_account_id"), receipt.get("operator_name"), receipt.get("operator_identity"),
        receipt.get("rule_version"), receipt.get("plan_hash"), receipt.get("result_json"), receipt.get("created_at"));
    restoreActorSnapshots(entry);
    accountIds.forEach(accounts::releaseForStoreExit);
  }

  private void restoreActorSnapshots(StoreExitJournal.Entry entry) {
    try {
      var result = json.readTree(String.valueOf(entry.receipt().get("result_json")));
      java.util.Set<Long> deleted = new java.util.HashSet<>();
      result.path("accountIds").forEach(id -> deleted.add(Long.parseLong(id.asText())));
      var snapshots = result.path("actorSnapshots");
      if (snapshots.isMissingNode()) {
        for (Long id : deleted) {
          if (accounts.requiresHistoricalName(id)) { throw new IllegalStateException("旧凭证缺少必要历史名称，不能猜测恢复"); }
        }
        return;
      }
      if (!snapshots.isObject()) { throw new IllegalStateException("退出名称快照不可核实"); }
      for (Long id : deleted) {
        if (accounts.requiresHistoricalName(id) && !snapshots.has(id.toString())) {
          throw new IllegalStateException("退出凭证遗漏必要历史名称，不能猜测恢复");
        }
      }
      var fields = snapshots.fields();
      while (fields.hasNext()) {
        var field = fields.next(); long id = Long.parseLong(field.getKey());
        if (!deleted.contains(id) || !field.getValue().isTextual() || field.getValue().asText().length() > 200) {
          throw new IllegalStateException("退出名称快照超出可信账号范围");
        }
        jdbc.update("INSERT INTO store_exit_actor_snapshots(account_id,display_name_at_exit) VALUES (?,?) ON DUPLICATE KEY UPDATE display_name_at_exit=VALUES(display_name_at_exit)", id, field.getValue().asText());
      }
    } catch (JsonProcessingException | NumberFormatException exception) { throw new IllegalStateException("退出名称凭证损坏", exception); }
  }

  public StoreExitResult result(long storeId) { return result(storeId, null); }

  /** Aggregate only the stores just deleted inside the already-authorized tenant transaction. */
  @Transactional(propagation = Propagation.MANDATORY)
  public StoreExitResult resultForTenant(long storeId, long tenantId) { return result(storeId, tenantId); }

  private StoreExitResult result(long storeId, Long authorizedTenant) {
    var rows = jdbc.queryForList("SELECT * FROM store_exit_operations WHERE store_id=?", storeId);
    if (rows.isEmpty() || java.util.Objects.requireNonNull(jdbc.queryForObject("SELECT COUNT(*) FROM stores WHERE id=?", Long.class, storeId), "数量查询缺少结果") > 0) {
      throw new IllegalArgumentException("没有可证明完成主数据清理的退出结果");
    }
    var row = rows.getFirst();
    if (authorizedTenant == null) {
      DataScope.requireAccess(identities.require(), row.get("store_created_by_account_id") == null
          ? null : number(row.get("store_created_by_account_id")));
    } else if (number(row.get("tenant_id")) != authorizedTenant
        || !java.util.Objects.equals(identities.require().accountId(), row.get("operator_account_id"))) {
      throw new org.springframework.security.access.AccessDeniedException("退出结果不属于本次租户操作");
    }
    boolean recoveryAttention = !StoreExitRecoveryState.ownsOperation(String.valueOf(row.get("operation_id")))
        && recovery.resultRequiresAttention(storeId);
    long pending = java.util.Objects.requireNonNull(jdbc.queryForObject("SELECT COUNT(*) FROM store_exit_tasks WHERE operation_id=? AND status<>'complete'",
        Long.class, row.get("operation_id")), "数量查询缺少结果");
    long blocked = java.util.Objects.requireNonNull(jdbc.queryForObject("SELECT COUNT(*) FROM store_exit_tasks WHERE operation_id=? AND status='blocked'",
        Long.class, row.get("operation_id")), "数量查询缺少结果");
    StoreExitMediaFollowup.State mediaState = mediaFollowup.inspect(String.valueOf(row.get("operation_id")));
    pending += mediaState.pending();
    blocked += mediaState.failed();
    try {
      var verified = json.readTree(String.valueOf(row.get("result_json")));
      if (!verified.path("verified").asBoolean() || !RULE_VERSION.equals(row.get("rule_version"))
          || !List.of("DB_COMMITTED", "COMPLETE").contains(row.get("status"))) {
        throw new IllegalStateException("退出凭证未证明清理校验完成");
      }
      List<String> retained = json.convertValue(verified.path("retained"),
          new com.fasterxml.jackson.core.type.TypeReference<List<String>>() { });
      return new StoreExitResult(String.valueOf(row.get("operation_id")), storeId, "CLEARED",
          blocked > 0 || recoveryAttention ? "ATTENTION" : pending == 0 && "COMPLETE".equals(row.get("status")) ? "COMPLETE" : "PENDING", pending, retained);
    } catch (JsonProcessingException exception) { throw new IllegalStateException("退出凭证无法校验", exception); }
  }

  public StoreExitResult existingResult(long storeId, String planHash) {
    StoreExitResult result = result(storeId);
    String original = jdbc.queryForObject("SELECT plan_hash FROM store_exit_operations WHERE store_id=?", String.class, storeId);
    if (!java.util.Objects.equals(original, planHash)) {
      throw new IllegalArgumentException("删除计划不匹配，请核对原操作结果");
    }
    return result;
  }

  @Transactional
  public void retry(long storeId) {
    var rows = jdbc.queryForList("SELECT * FROM store_exit_operations WHERE store_id=? FOR UPDATE", storeId);
    Map<String, Object> receipt = rows.isEmpty() ? journal.entries().stream()
        .filter(e -> e.storeId() == storeId && "COMMITTED".equals(e.stage())).findFirst()
        .orElseThrow(() -> new IllegalArgumentException("退出凭证不存在，不能自动重试")).receipt() : rows.getFirst();
    Object creator = receipt.get("store_created_by_account_id");
    DataScope.requireAccess(identities.require(), creator == null ? null : number(creator));
    jdbc.update("""
        INSERT INTO store_exit_events(operation_id,store_id,tenant_id,operator_account_id,result,reason_code)
        VALUES (?,?,?,?,'PENDING','MANUAL_RETRY')
        """, receipt.get("operation_id"), storeId, receipt.get("tenant_id"), identities.require().accountId());
    jdbc.update("""
        UPDATE store_exit_tasks SET status='pending',attempts=0,next_attempt_at=CURRENT_TIMESTAMP(6)
        WHERE operation_id=? AND status IN ('failed','blocked')
        AND NOT(last_error_code<=>'RESTORE_RELEASE_TIME_UNCERTAIN')
        """, receipt.get("operation_id"));
  }

  private Map<String, Object> target(long storeId, boolean lock) {
    var rows = jdbc.queryForList("SELECT id,tenant_id,name,status,created_by_account_id FROM stores WHERE id=?" + (lock ? " FOR UPDATE" : ""), storeId);
    if (rows.isEmpty()) { throw new IllegalArgumentException("门店不存在；需核对删除凭证和残留，不能直接认定已完成"); }
    return rows.getFirst();
  }

  private void authorize(Map<String, Object> store, boolean tenantExit) {
    CurrentIdentity actor = identities.require();
    Long creator = tenantExit
        ? jdbc.queryForObject("SELECT created_by_account_id FROM tenants WHERE id=?", Long.class, store.get("tenant_id"))
        : (store.get("created_by_account_id") == null ? null : number(store.get("created_by_account_id")));
    DataScope.requireAccess(actor, creator);
  }

  public boolean hasForeignTenantRelations(long tenantId) {
    for (String table : registry.tables()) {
      Integer columns = java.util.Objects.requireNonNull(jdbc.queryForObject("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND COLUMN_NAME IN ('tenant_id','store_id')", Integer.class, table), "数量查询缺少结果");
      if (columns == 2 && java.util.Objects.requireNonNull(jdbc.queryForObject("SELECT COUNT(*) FROM " + table
          + " relation WHERE relation.tenant_id=? AND relation.store_id IS NOT NULL AND NOT EXISTS"
          + "(SELECT 1 FROM stores parent WHERE parent.id=relation.store_id AND parent.tenant_id=?)",
          Long.class, tenantId, tenantId), "数量查询缺少结果") > 0) { return true; }
    }
    return false;
  }

  private boolean foreignReferences(StoreExitScope scope) {
    for (String table : registry.tables()) {
      Long columns = java.util.Objects.requireNonNull(jdbc.queryForObject("""
          SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE()
          AND TABLE_NAME=? AND COLUMN_NAME IN ('store_id','tenant_id')
          """, Long.class, table), "数量查询缺少结果");
      if (columns == 2 && java.util.Objects.requireNonNull(jdbc.queryForObject(
          "SELECT COUNT(*) FROM " + table + " WHERE store_id=? AND NOT(tenant_id<=>?)",
          Long.class, scope.storeId(), scope.tenantId()), "数量查询缺少结果") > 0) { return true; }
    }
    if (java.util.Objects.requireNonNull(jdbc.queryForObject("SELECT COUNT(*) FROM suppliers WHERE store_id=? AND NOT(owner_scope='store' AND owner_id=?)",
        Long.class, scope.storeId(), scope.storeId()), "数量查询缺少结果") > 0) { return true; }
    Long supplierRefs = java.util.Objects.requireNonNull(jdbc.queryForObject("""
        SELECT COUNT(*) FROM suppliers s WHERE s.store_id=? AND (
          EXISTS(SELECT 1 FROM slab_inventory p WHERE p.supplier_id=s.id) OR
          EXISTS(SELECT 1 FROM finished_products p WHERE p.supplier_id=s.id) OR
          EXISTS(SELECT 1 FROM accessory_products p WHERE p.supplier_id=s.id))
        """, Long.class, scope.storeId()), "数量查询缺少结果");
    Long categoryRefs = java.util.Objects.requireNonNull(jdbc.queryForObject("""
        SELECT COUNT(*) FROM store_categories c WHERE c.store_id=? AND (
          EXISTS(SELECT 1 FROM store_categories child WHERE child.parent_id=c.id AND child.store_id<>c.store_id) OR
          EXISTS(SELECT 1 FROM store_finished_products p WHERE p.store_category_id=c.id AND p.store_id<>c.store_id) OR
          EXISTS(SELECT 1 FROM store_accessory_products p WHERE p.store_category_id=c.id AND p.store_id<>c.store_id) OR
          EXISTS(SELECT 1 FROM store_price_rules p WHERE p.category_id=c.id AND p.store_id<>c.store_id))
        """, Long.class, scope.storeId()), "数量查询缺少结果");
    Long roleRefs = java.util.Objects.requireNonNull(jdbc.queryForObject("""
        SELECT COUNT(*) FROM roles r WHERE r.store_id=? AND (
          EXISTS(SELECT 1 FROM account_roles a WHERE a.role_id=r.id AND NOT(a.store_id<=>r.store_id)) OR
          EXISTS(SELECT 1 FROM store_price_rules p WHERE p.role_id=r.id AND p.store_id<>r.store_id))
        """, Long.class, scope.storeId()), "数量查询缺少结果");
    return supplierRefs > 0 || categoryRefs > 0 || roleRefs > 0;
  }

  private void auditFailure(String operation, long store, long tenant, Long actor, String result) {
    try {
      auditTransaction.executeWithoutResult(status -> jdbc.update("""
          INSERT INTO store_exit_events(operation_id,store_id,tenant_id,operator_account_id,result,reason_code)
          VALUES (?,?,?,?,?,?)
          """, operation, store, tenant, actor, result, "TRANSACTION_NOT_COMMITTED"));
    } catch (RuntimeException exception) { LOG.error("Store exit failure audit unavailable: {}", operation, exception); }
  }

  private Map<String, Long> inspectModule(StoreExitModule module, StoreExitScope scope) {
    Map<String, Long> counts = module.inspect(jdbc, scope);
    if (counts == null || !counts.keySet().equals(new java.util.HashSet<>(module.tables()))
        || counts.values().stream().anyMatch(count -> count == null || count < 0)) {
      throw new IllegalStateException("门店退出模块未完整报告实际数据范围：" + module.id());
    }
    return counts;
  }

  private String encode(Object value) {
    try { return json.writeValueAsString(value); }
    catch (JsonProcessingException exception) { throw new IllegalStateException("门店退出计划无法序列化", exception); }
  }
  private static long number(Object value) { return value instanceof Number number ? number.longValue() : Long.parseLong(String.valueOf(value)); }
}

package com.zdm.platform.storeexit;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;

/** A successful handoff is not proof that the downstream media job has finished. */
@Component
public class StoreExitMediaFollowup {
  private final JdbcTemplate jdbc;
  public StoreExitMediaFollowup(JdbcTemplate jdbc) { this.jdbc = jdbc; }

  public record State(long pending, long failed) { }

  public State inspect(String operation) {
    return jdbc.queryForObject("""
        SELECT COUNT(*) AS pending, COALESCE(SUM(EXISTS(
          SELECT 1 FROM media_cleanup_tasks failure WHERE failure.media_id=t.media_id AND failure.status='failed')),0) AS failed
        FROM store_exit_tasks t
        WHERE t.operation_id=? AND t.media_id>0 AND t.status='complete'
          AND EXISTS(SELECT 1 FROM media_cleanup_tasks m WHERE m.media_id=t.media_id
            AND m.status IN ('pending','processing','failed'))
        """, (rs, row) -> new State(rs.getLong("pending"), rs.getLong("failed")), operation);
  }
}

package com.zdm.platform.storeexit;

import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;

/** Internal participation contract; never accepts a client-provided organization context. */
public interface StoreExitModule {
  String id();
  List<String> tables();
  default List<String> dependsOn() { return List.of(); }
  Map<String, Long> inspect(JdbcTemplate jdbc, StoreExitScope scope);
  default List<Long> referencedAccounts(JdbcTemplate jdbc, StoreExitScope scope, StoreExitAccountReferences references) {
    if (tables().stream().anyMatch(table -> !references.liveFields(table).isEmpty())) {
      throw new IllegalStateException("门店退出模块缺少账号候选收集：" + id());
    }
    return List.of();
  }
  void execute(JdbcTemplate jdbc, StoreExitScope scope);
  void verify(JdbcTemplate jdbc, StoreExitScope scope);
}

package com.zdm.platform.storeexit;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;

@Component
public final class StoreExitRegistry {
  public static final Map<String, String> STATE_ACTIVITY_PARENTS = Map.of(
      "store-finished/store", "store_finished_products", "store-accessory/store", "store_accessory_products");
  private final List<StoreExitModule> modules;

  public StoreExitRegistry(List<StoreExitModule> extensions) {
    List<StoreExitModule> all = new ArrayList<>();
    all.add(indirect("selection-batch-items", "store_selection_batch_items", "batch_id", "store_selection_batches"));
    all.add(new SqlModule("selection", List.of("store_selection_items", "store_selection_batches"),
        List.of("selection-batch-items"), scope -> new Clause("tenant_id=? AND store_id=?",
            new Object[]{scope.tenantId(), scope.storeId()})));
    all.add(sql("payment", List.of("store_payment_name_events", "store_payment_names")));
    all.add(indirect("customer-followups", "store_customer_followups", "customer_id", "store_customers"));
    all.add(sql("customers", List.of("store_customers"), List.of("customer-followups")));
    all.add(indirect("finished-prices", "store_finished_sale_prices", "listing_id", "store_finished_products"));
    all.add(sql("finished-listings", List.of("store_finished_products"), List.of("finished-prices", "store-product-state")));
    all.add(indirect("accessory-prices", "store_accessory_sale_prices", "listing_id", "store_accessory_products"));
    all.add(sql("accessory-listings", List.of("store_accessory_products"), List.of("accessory-prices", "store-product-state")));
    all.add(new SqlModule("store-product-state", List.of("product_state_activity"), List.of(), scope -> {
      List<Object> args = new ArrayList<>();
      List<String> predicates = new ArrayList<>();
      STATE_ACTIVITY_PARENTS.entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(entry -> {
        List<Long> ids = scope.ids(entry.getValue());
        if (!ids.isEmpty()) {
          predicates.add("(kind=? AND record_id IN (" + String.join(",", java.util.Collections.nCopies(ids.size(), "?")) + "))");
          args.add(entry.getKey().substring(0, entry.getKey().indexOf('/'))); args.addAll(ids);
        }
      });
      return new Clause(predicates.isEmpty() ? "1=0" : "business_client_code='store' AND (" + String.join(" OR ", predicates) + ")", args.toArray());
    }));
    all.add(sql("product-logs", List.of("store_finished_operation_logs", "store_accessory_operation_logs")));
    all.add(indirect("sessions", "auth_sessions", "identity_id", "account_identities"));
    all.add(indirect("invite-history", "employee_invite_acceptances", "invite_id", "employee_invites"));
    all.add(sql("invites", List.of("employee_invites"), List.of("invite-history")));
    all.add(sql("memberships", List.of("account_roles", "employees", "account_identities"), List.of("sessions")));
    all.add(indirect("role-permissions", "role_permissions", "role_id", "roles"));
    all.add(sql("price-rules", List.of("store_price_rules")));
    all.add(sql("roles", List.of("roles"), List.of("memberships", "role-permissions", "price-rules")));
    all.add(indirect("supplier-links", "supplier_supply_type_links", "supplier_id", "suppliers"));
    all.add(sql("suppliers", List.of("suppliers"), List.of("supplier-links")));
    all.add(new SqlModule("categories", List.of("store_categories"), List.of("finished-listings", "accessory-listings", "price-rules"),
        scope -> new Clause("store_id=?", new Object[]{scope.storeId()})) {
      @Override public void execute(JdbcTemplate jdbc, StoreExitScope scope) {
        int removed;
        do {
          removed = jdbc.update("DELETE c FROM store_categories c LEFT JOIN store_categories child ON child.parent_id=c.id "
              + "WHERE c.store_id=? AND child.id IS NULL", scope.storeId());
        } while (removed > 0);
        verify(jdbc, scope);
      }
    });
    all.addAll(extensions);
    modules = order(all);
  }

  public List<StoreExitModule> modules() { return List.copyOf(modules); }

  public Set<String> tables() {
    Set<String> result = new HashSet<>();
    modules.forEach(module -> result.addAll(module.tables()));
    return Set.copyOf(result);
  }

  private static List<StoreExitModule> order(List<StoreExitModule> all) {
    Map<String, StoreExitModule> pending = new LinkedHashMap<>();
    Set<String> tables = new HashSet<>();
    for (StoreExitModule module : all) {
      if (module.id().isBlank() || module.tables().isEmpty() || pending.putIfAbsent(module.id(), module) != null) {
        throw new IllegalStateException("门店退出模块登记重复或为空");
      }
      for (String table : module.tables()) {
        if (!table.matches("[a-z_]+") || !tables.add(table)) {
          throw new IllegalStateException("门店退出数据处理归口重复或非法");
        }
      }
    }
    List<StoreExitModule> sorted = new ArrayList<>();
    Set<String> done = new HashSet<>();
    while (!pending.isEmpty()) {
      var ready = pending.values().stream().filter(m -> done.containsAll(m.dependsOn())).findFirst();
      if (ready.isEmpty()) { throw new IllegalStateException("门店退出模块依赖缺失或循环"); }
      StoreExitModule module = ready.get();
      pending.remove(module.id()); done.add(module.id()); sorted.add(module);
    }
    return List.copyOf(sorted);
  }

  private static StoreExitModule sql(String id, List<String> tables) { return sql(id, tables, List.of()); }
  private static StoreExitModule sql(String id, List<String> tables, List<String> depends) {
    return new SqlModule(id, tables, depends, s -> new Clause("store_id=?", new Object[]{s.storeId()}));
  }
  private static StoreExitModule indirect(String id, String table, String column, String parent) {
    return new SqlModule(id, List.of(table), List.of(), scope -> {
      List<Long> ids = scope.ids(parent);
      return ids.isEmpty() ? new Clause("1=0", new Object[0])
          : new Clause(column + " IN (" + String.join(",", java.util.Collections.nCopies(ids.size(), "?")) + ")", ids.toArray());
    });
  }

  private record Clause(String sql, Object[] args) { }

  private static class SqlModule implements StoreExitModule {
    private final String id;
    private final List<String> tables;
    private final List<String> depends;
    private final Function<StoreExitScope, Clause> clause;
    SqlModule(String id, List<String> tables, List<String> depends, Function<StoreExitScope, Clause> clause) {
      this.id = id; this.tables = List.copyOf(tables); this.depends = List.copyOf(depends); this.clause = clause;
    }
    @Override public String id() { return id; }
    @Override public List<String> tables() { return tables; }
    @Override public List<String> dependsOn() { return depends; }
    @Override public Map<String, Long> inspect(JdbcTemplate jdbc, StoreExitScope scope) {
      Map<String, Long> counts = new LinkedHashMap<>();
      Clause condition = clause.apply(scope);
      tables.forEach(table -> counts.put(table, jdbc.queryForObject("SELECT COUNT(*) FROM " + table + " WHERE " + condition.sql(), Long.class, condition.args())));
      return counts;
    }
    @Override public List<Long> referencedAccounts(JdbcTemplate jdbc, StoreExitScope scope, StoreExitAccountReferences references) {
      java.util.Set<Long> accounts = new java.util.TreeSet<>();
      Clause condition = clause.apply(scope);
      for (String table : tables) {
        for (String field : references.liveFields(table)) {
          if (!field.matches("[a-z_]+")) { throw new IllegalStateException("账号引用字段不合法"); }
          accounts.addAll(jdbc.queryForList("SELECT DISTINCT " + field + " FROM " + table
              + " WHERE (" + condition.sql() + ") AND " + field + " IS NOT NULL AND EXISTS"
              + " (SELECT 1 FROM accounts a WHERE a.id=" + table + "." + field + ")", Long.class, condition.args()));
        }
      }
      return List.copyOf(accounts);
    }
    @Override public void execute(JdbcTemplate jdbc, StoreExitScope scope) {
      Clause condition = clause.apply(scope);
      tables.forEach(table -> jdbc.update("DELETE FROM " + table + " WHERE " + condition.sql(), condition.args()));
    }
    @Override public void verify(JdbcTemplate jdbc, StoreExitScope scope) {
      if (inspect(jdbc, scope).values().stream().anyMatch(count -> count != 0)) {
        throw new IllegalStateException("门店退出残留校验失败：" + id);
      }
    }
  }
}

package com.zdm.platform.tenant;

import com.zdm.platform.account.CreatorAwareService;
import com.zdm.platform.security.CurrentIdentityProvider;
import java.util.Arrays;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;

@Service
public class TenantService extends CreatorAwareService<TenantMapper, Tenant> {
  private static final Set<String> BUSINESS_TYPES =
      Set.of("cityPartner", "slabSupplier", "finishedSupplier", "factory");

  private final JdbcTemplate jdbcTemplate;
  private final com.zdm.platform.account.AccountLifecycleService accountLifecycle;
  private final CurrentIdentityProvider identityProvider;
  private final com.zdm.platform.storeexit.StoreExitCoordinator exits;

  public TenantService(
      JdbcTemplate jdbcTemplate,
      CurrentIdentityProvider identityProvider,
      com.zdm.platform.account.AccountLifecycleService accountLifecycle,
      com.zdm.platform.storeexit.StoreExitCoordinator exits) {
    this.jdbcTemplate = jdbcTemplate;
    this.identityProvider = identityProvider;
    this.accountLifecycle = accountLifecycle;
    this.exits = exits;
  }

  public List<Tenant> listTenants() {
    return withPersonalProfiles(lambdaQuery()
        .orderByDesc(Tenant::getCreatedAt)
        .orderByDesc(Tenant::getId)
        .list());
  }

  @Transactional
  public Tenant createTenant(Tenant tenant) {
    List<String> businesses = List.of();
    tenant.setBusinessTypes("");
    tenant.setCreatedByAccountId(identityProvider.require().accountId());
    requireAvailableTenantPhone(tenant.getContactPhone(), null);
    Long accountId;
    try {
      accountId = findOrCreateAccount(tenant.getContactPhone(), tenant.getName());
      tenant.setAccountId(accountId);
      save(tenant);
    } catch (DuplicateKeyException exception) {
      throw new IllegalArgumentException("该手机号已存在", exception);
    }
    syncBusinesses(tenant.getId(), businesses);
    syncTenantAdminIdentity(tenant, accountId);
    return getById(tenant.getId());
  }

  @Transactional
  public Tenant updateTenant(Long id, Tenant payload) {
    Tenant existing = getById(id);
    if (existing == null) {
      throw new IllegalArgumentException("租户不存在");
    }
    existing = lockTenant(id);
    Long ownerAccountId = requireOwnerAccountId(id);
    accountLifecycle.lockAccount(ownerAccountId);
    requireAvailableTenantPhone(payload.getContactPhone(), id);
    requireAvailablePhone(payload.getContactPhone(), ownerAccountId);
    payload.setId(id);
    payload.setAccountId(ownerAccountId);
    payload.setStatus(existing.getStatus());
    payload.setBusinessTypes(existing.getBusinessTypes());
    payload.setCreatedByAccountId(existing.getCreatedByAccountId());
    try {
      updateById(payload);
      jdbcTemplate.update(
          "UPDATE accounts SET phone = ?, display_name = ? WHERE id = ?",
          payload.getContactPhone(),
          payload.getName(),
          ownerAccountId);
    } catch (DuplicateKeyException exception) {
      throw new IllegalArgumentException("该手机号已存在", exception);
    }
    return getById(id);
  }

  @Transactional
  public Tenant updateBusinesses(Long id, String businessTypes) {
    Tenant existing = requireTenant(id);
    List<String> businesses = normalizeBusinesses(businessTypes);
    existing.setBusinessTypes(String.join(",", businesses));
    updateById(existing);
    syncBusinesses(id, businesses);
    return getById(id);
  }

  @Transactional
  public Tenant updateStatus(Long id, String status) {
    Tenant existing = requireTenant(id);
    if (!Set.of("enabled", "disabled").contains(status)) {
      throw new IllegalArgumentException("存在无效的租户状态");
    }
    existing.setStatus(status);
    updateById(existing);
    if ("disabled".equals(status)) {
      jdbcTemplate.update(
          """
          UPDATE stores
          SET status = 'disabled', archived_by_tenant = 1
          WHERE tenant_id = ? AND status = 'enabled'
          """,
          id);
      jdbcTemplate.update(
          """
          UPDATE auth_sessions
          SET revoked_at = CURRENT_TIMESTAMP
          WHERE revoked_at IS NULL
            AND identity_id IN (SELECT id FROM account_identities WHERE tenant_id = ?)
          """,
          id);
    } else {
      jdbcTemplate.update(
          """
          UPDATE stores
          SET status = 'enabled', archived_by_tenant = 0
          WHERE tenant_id = ?
            AND status = 'disabled'
            AND archived_by_tenant = 1
          """,
          id);
    }
    return getById(id);
  }

  public TenantPurgePreview getPurgePreview(Long id) {
    Tenant existing = requireTenant(id);
    com.zdm.platform.security.DataScope.requireAccess(identityProvider.require(), existing.getCreatedByAccountId());
    return buildPurgePreview(existing);
  }

  @Transactional
  public TenantPurgeResult purgeTenant(Long id, String confirmationName, Map<Long, String> storePlans) {
    Tenant existing = lockTenant(id);
    com.zdm.platform.security.DataScope.requireAccess(identityProvider.require(), existing.getCreatedByAccountId());
    if (!existing.getName().equals(confirmationName)) {
      throw new IllegalArgumentException("请输入完整租户名称确认删除");
    }
    exits.lockTenantStores(id);
    List<Long> candidateAccountIds = findTenantAccountIds(id);
    Set<Long> relationshipAccountIds = new HashSet<>(findTenantRelationshipAccountIds(id));
    candidateAccountIds.forEach(accountLifecycle::lockAccount);
    Set<Long> storeOnlyAccounts = candidateAccountIds.stream()
        .filter(account -> accountLifecycle.isStoreOnlyExitAccount(account, id)).collect(java.util.stream.Collectors.toSet());
    TenantPurgePreview preview = buildPurgePreview(existing);
    if (!preview.eligible()) {
      throw new IllegalArgumentException(preview.blockers().getFirst());
    }
    Set<Long> protectedAccounts = new HashSet<>();
    candidateAccountIds.stream().filter(accountLifecycle::isProtected).forEach(protectedAccounts::add);
    if (storePlans == null || !storePlans.equals(preview.storePlans())) {
      throw new IllegalArgumentException("门店删除范围或规则已变化，请重新预检并确认");
    }
    for (var plan : new java.util.TreeMap<>(storePlans).entrySet()) {
      exits.execute(plan.getKey(), plan.getValue(), true);
    }

    jdbcTemplate.update(
        "DELETE FROM auth_sessions WHERE identity_id IN (SELECT id FROM account_identities WHERE tenant_id = ? AND store_id IS NULL)",
        id);
    jdbcTemplate.update("DELETE FROM account_roles WHERE tenant_id = ? AND store_id IS NULL", id);
    jdbcTemplate.update(
        "DELETE FROM role_permissions WHERE role_id IN (SELECT id FROM roles WHERE tenant_id = ? AND store_id IS NULL)",
        id);
    jdbcTemplate.update("DELETE FROM account_identities WHERE tenant_id = ? AND store_id IS NULL", id);
    deleteTenantProductCategories(id);
    jdbcTemplate.update("DELETE FROM employee_invite_acceptances WHERE invite_id IN (SELECT id FROM employee_invites WHERE tenant_id=? AND store_id IS NULL)", id);
    jdbcTemplate.update("DELETE FROM employee_invites WHERE tenant_id = ? AND store_id IS NULL", id);
    jdbcTemplate.update("DELETE FROM employees WHERE tenant_id = ? AND store_id IS NULL", id);
    int employeeDeleteCount = preview.employeeCount();
    jdbcTemplate.update("DELETE FROM roles WHERE tenant_id = ? AND store_id IS NULL", id);
    int roleDeleteCount = preview.roleCount();
    int storeDeleteCount = preview.storeCount();
    jdbcTemplate.update("DELETE FROM tenant_businesses WHERE tenant_id = ?", id);
    int tenantDeleteCount = jdbcTemplate.update("DELETE FROM tenants WHERE id = ?", id);
    java.util.Set<Long> phoneAccounts = candidateAccountIds.stream().filter(accountLifecycle::hasPhoneCredential)
        .collect(java.util.stream.Collectors.toSet());
    int deletedAccounts = 0;
    int retainedAccounts = 0;
    int releasedPhones = 0;
    for (Long accountId : candidateAccountIds) {
      var disposition = protectedAccounts.contains(accountId)
          ? com.zdm.platform.account.AccountLifecycleService.Disposition.KEEP
          : storeOnlyAccounts.contains(accountId) ? accountLifecycle.releaseForStoreExit(accountId)
              : accountLifecycle.releaseIfUnbound(accountId);
      if (disposition == com.zdm.platform.account.AccountLifecycleService.Disposition.DELETE) {
        deletedAccounts++;
      } else if (relationshipAccountIds.contains(accountId)) { retainedAccounts++; }
      if (disposition != com.zdm.platform.account.AccountLifecycleService.Disposition.KEEP && phoneAccounts.contains(accountId)) {
        releasedPhones++;
      }
    }
    storePlans.keySet().forEach(storeId -> exits.recordAccountOutcome(storeId, candidateAccountIds));
    return new TenantPurgeResult(
        tenantDeleteCount,
        storeDeleteCount,
        employeeDeleteCount,
        roleDeleteCount,
        deletedAccounts,
        retainedAccounts,
        releasedPhones,
        storePlans.keySet().stream().sorted().map(storeId -> exits.resultForTenant(storeId, id)).toList());
  }

  public boolean hasEnabledBusiness(Long tenantId, String businessType) {
    if (!BUSINESS_TYPES.contains(businessType)) {
      return false;
    }
    Integer count = jdbcTemplate.queryForObject(
        """
        SELECT COUNT(*)
        FROM tenant_businesses tb
        JOIN tenants t ON t.id = tb.tenant_id AND t.status = 'enabled'
        WHERE tb.tenant_id = ? AND tb.business_type = ? AND tb.status = 'enabled'
        """,
        Integer.class,
        tenantId,
        businessType);
    return count != null && count > 0;
  }

  private List<String> normalizeBusinesses(String value) {
    if (!StringUtils.hasText(value)) {
      return List.of();
    }
    List<String> values = Arrays.stream(value.split(","))
        .map(String::trim)
        .filter(StringUtils::hasText)
        .distinct()
        .toList();
    List<String> invalid = values.stream().filter(type -> !BUSINESS_TYPES.contains(type)).toList();
    if (!invalid.isEmpty()) {
      throw new IllegalArgumentException("存在无效的租户业务类型");
    }
    return values;
  }

  private Tenant requireTenant(Long id) {
    Tenant tenant = getById(id);
    if (tenant == null) {
      throw new IllegalArgumentException("租户不存在");
    }
    return tenant;
  }

  private void syncBusinesses(Long tenantId, List<String> businesses) {
    jdbcTemplate.update("DELETE FROM tenant_businesses WHERE tenant_id = ?", tenantId);
    for (String business : businesses) {
      jdbcTemplate.update(
          "INSERT INTO tenant_businesses (tenant_id, business_type, status) VALUES (?, ?, 'enabled')",
          tenantId,
          business);
    }
  }

  private Long findOrCreateAccount(String phone, String displayName) {
    return accountLifecycle.findOrCreate(phone, displayName).id();
  }

  private Optional<Long> findAccountId(String phone) {
    return jdbcTemplate.query(
        "SELECT id FROM accounts WHERE phone = ? LIMIT 1",
        (rs, rowNum) -> rs.getLong("id"),
        phone).stream().findFirst();
  }

  private void requireAvailablePhone(String phone, Long ownerAccountId) {
    findAccountId(phone).ifPresent(accountId -> {
      if (!accountId.equals(ownerAccountId)) {
        throw new IllegalArgumentException("该手机号已属于其他账号");
      }
    });
  }

  private void requireAvailableTenantPhone(String phone, Long tenantId) {
    Integer count = tenantId == null
        ? jdbcTemplate.queryForObject(
            "SELECT COUNT(*) FROM tenants t JOIN accounts a ON a.id=t.account_id WHERE a.phone = ?", Integer.class, phone)
        : jdbcTemplate.queryForObject(
            "SELECT COUNT(*) FROM tenants t JOIN accounts a ON a.id=t.account_id WHERE a.phone = ? AND t.id <> ?", Integer.class, phone, tenantId);
    if (count != null && count > 0) {
      throw new IllegalArgumentException("该手机号已存在");
    }
  }


  private Long requireOwnerAccountId(Long tenantId) {
    return jdbcTemplate.query(
        "SELECT account_id FROM tenants WHERE id = ?",
        (rs, rowNum) -> rs.getLong("account_id"),
        tenantId).stream().findFirst().orElseThrow(() -> new IllegalArgumentException("租户管理员身份不存在"));
  }

  private void syncTenantAdminIdentity(Tenant tenant, Long accountId) {
    jdbcTemplate.update(
        """
        INSERT INTO account_identities
          (account_id, client_code, identity_type, subject_id, tenant_id, store_id, status)
        VALUES (?, 'admin', 'tenant_admin', ?, ?, NULL, ?)
        ON DUPLICATE KEY UPDATE account_id = VALUES(account_id), status = VALUES(status)
        """,
        accountId,
        tenant.getId(),
        tenant.getId(),
        tenant.getStatus());
  }

  private Tenant lockTenant(Long id) {
    Tenant locked = jdbcTemplate.query(
        "SELECT * FROM tenants WHERE id = ? FOR UPDATE",
        (rs, rowNum) -> {
          Tenant tenant = new Tenant();
          tenant.setId(rs.getLong("id"));
          tenant.setAccountId(rs.getLong("account_id"));
          tenant.setBusinessTypes(rs.getString("business_types"));
          tenant.setRemark(rs.getString("remark"));
          tenant.setStatus(rs.getString("status"));
          tenant.setCreatedByAccountId(rs.getObject("created_by_account_id", Long.class));
          return tenant;
        },
        id).stream().findFirst().orElseThrow(() -> new IllegalArgumentException("租户不存在或已删除"));
    withPersonalProfiles(List.of(locked));
    return creatorNames.attach(locked);
  }

  private TenantPurgePreview buildPurgePreview(Tenant tenant) {
    Long tenantId = tenant.getId();
    List<String> blockers = new ArrayList<>();
    if (!"disabled".equals(tenant.getStatus())) {
      blockers.add("请先归档租户");
    }
    if (count(
        """
        SELECT COUNT(*)
        FROM (SELECT category_id FROM finished_products UNION ALL SELECT category_id FROM accessory_products) fp
        JOIN product_categories pc ON pc.id = fp.category_id
        WHERE pc.tenant_id = ?
        """,
        tenantId) > 0
        || count(
            """
            SELECT COUNT(*)
            FROM product_categories child
            JOIN product_categories parent ON parent.id = child.parent_id
            WHERE parent.tenant_id = ?
              AND (child.tenant_id IS NULL OR child.tenant_id <> ?)
            """,
            tenantId,
            tenantId) > 0) {
      blockers.add("该租户存在暂不支持删除的跨组织业务数据");
    }

    if (exits.hasForeignTenantRelations(tenantId)) { blockers.add("该租户存在归属不一致的门店关系，请先核实"); }
    Map<Long, String> storePlans = new java.util.TreeMap<>();
    for (Long storeId : jdbcTemplate.queryForList("SELECT id FROM stores WHERE tenant_id=? ORDER BY id", Long.class, tenantId)) {
      var storePreview = exits.previewForTenant(storeId);
      storePlans.put(storeId, storePreview.planHash());
      blockers.addAll(storePreview.blockers());
    }
    List<Long> candidateAccountIds = findTenantAccountIds(tenantId);
    Set<Long> relationshipAccountIds = new HashSet<>(findTenantRelationshipAccountIds(tenantId));
    int accountDeleteCount = 0;
    int accountRetainCount = 0;
    int phoneReleaseCount = 0;
    for (Long accountId : candidateAccountIds) {
      var disposition = accountLifecycle.assessForTenantExit(accountId, storePlans.keySet(), tenantId);
      if (disposition == com.zdm.platform.account.AccountLifecycleService.Disposition.DELETE) {
        accountDeleteCount++;
      } else if (relationshipAccountIds.contains(accountId)) { accountRetainCount++; }
      if (disposition != com.zdm.platform.account.AccountLifecycleService.Disposition.KEEP && accountLifecycle.hasPhoneCredential(accountId)) {
        phoneReleaseCount++;
      }
    }
    return new TenantPurgePreview(
        blockers.isEmpty(),
        tenant.getName(),
        count("SELECT COUNT(*) FROM stores WHERE tenant_id = ?", tenantId),
        count("SELECT COUNT(*) FROM employees WHERE tenant_id = ?", tenantId),
        count("SELECT COUNT(*) FROM roles WHERE tenant_id = ?", tenantId),
        accountDeleteCount,
        accountRetainCount,
        phoneReleaseCount,
        blockers, storePlans);
  }

  private List<Long> findTenantAccountIds(Long tenantId) {
    java.util.Set<Long> result = new java.util.TreeSet<>(findTenantRelationshipAccountIds(tenantId));
    for (Long store : jdbcTemplate.queryForList("SELECT id FROM stores WHERE tenant_id=? ORDER BY id", Long.class, tenantId)) {
      result.addAll(accountLifecycle.storeExitCandidates(
          com.zdm.platform.storeexit.StoreExitScope.capture(jdbcTemplate, store, tenantId)));
    }
    return List.copyOf(result);
  }

  private List<Long> findTenantRelationshipAccountIds(Long tenantId) {
    return jdbcTemplate.queryForList(
        """
        SELECT DISTINCT account_id
        FROM (
          SELECT account_id FROM account_identities WHERE tenant_id = ?
          UNION ALL
          SELECT account_id FROM employees WHERE tenant_id = ? AND account_id IS NOT NULL
          UNION ALL
          SELECT account_id FROM account_roles WHERE tenant_id = ?
        ) tenant_accounts
        WHERE account_id IS NOT NULL
        ORDER BY account_id
        """,
        Long.class,
        tenantId,
        tenantId,
        tenantId);
  }

  private void deleteTenantProductCategories(Long tenantId) {
    List<Map<String, Object>> categoryRows = jdbcTemplate.queryForList(
        "SELECT id, parent_id FROM product_categories WHERE tenant_id = ?",
        tenantId);
    Set<Long> remaining = new LinkedHashSet<>();
    Map<Long, Long> parents = new HashMap<>();
    for (Map<String, Object> row : categoryRows) {
      Long id = ((Number) row.get("id")).longValue();
      remaining.add(id);
      Object parentId = row.get("parent_id");
      parents.put(id, parentId == null ? null : ((Number) parentId).longValue());
    }
    if (remaining.isEmpty()) {
      return;
    }
    jdbcTemplate.update(
        "DELETE template FROM category_template_versions template JOIN product_categories pc ON pc.id = template.category_id WHERE pc.tenant_id = ?",
        tenantId);
    while (!remaining.isEmpty()) {
      List<Long> leaves = remaining.stream()
          .filter(id -> remaining.stream().noneMatch(other -> id.equals(parents.get(other))))
          .toList();
      if (leaves.isEmpty()) {
        throw new IllegalStateException("租户商品分类层级异常，无法安全删除");
      }
      for (Long categoryId : leaves) {
        jdbcTemplate.update("DELETE FROM product_categories WHERE id = ?", categoryId);
        remaining.remove(categoryId);
      }
    }
  }

  private int count(String sql, Object... args) {
    Integer value = jdbcTemplate.queryForObject(sql, Integer.class, args);
    return value == null ? 0 : value;
  }
  private List<Tenant> withPersonalProfiles(List<Tenant> tenants) {
    var ids = tenants.stream().map(Tenant::getAccountId).distinct().toList();
    if (ids.isEmpty()) {
      return tenants;
    }
    String placeholders = String.join(",", java.util.Collections.nCopies(ids.size(), "?"));
    var profiles = jdbcTemplate.query("SELECT id,display_name,phone FROM accounts WHERE id IN (" + placeholders + ")",
        (rs, row) -> new PersonalProfile(rs.getLong("id"), rs.getString("display_name"), rs.getString("phone")), ids.toArray());
    var byId = profiles.stream().collect(java.util.stream.Collectors.toMap(PersonalProfile::accountId, value -> value));
    for (Tenant tenant : tenants) {
      PersonalProfile profile = byId.get(tenant.getAccountId());
      if (profile == null) {
        throw new IllegalArgumentException("租户管理员账号不存在");
      }
      tenant.setName(profile.name());
      tenant.setContactPhone(profile.phone());
    }
    return tenants;
  }

  private record PersonalProfile(Long accountId, String name, String phone) {}

  @Override
  public Tenant getById(java.io.Serializable id) {
    Tenant entity = super.getById(id);
    if (entity != null) {
      com.zdm.platform.security.DataScope.requireAccess(
          identityProvider.require(), entity.getCreatedByAccountId());
      withPersonalProfiles(List.of(entity));
    }
    return entity;
  }

}

